class Event {
public:
    using Ptr = std::shared_ptr<Event>;

    using Clock = std::chrono::system_clock;

    /**
     * @brief Create an event.
     *
     * @param level The event level.
     * @param location The event location.
     * @param thread_id The ID of the thread where the event occurred.
     * @param time The event time.
     *
     * @todo Replace @p std::experimental::source_location with @p std::source_location.
     */
    static Ptr Create(log::Level level,
                      std::experimental::source_location location =
                          std::experimental::source_location::current(),
                      std::uint32_t thread_id = CurrentThreadId(),
                      Clock::time_point time = Clock::now()) noexcept;

    Event(const Event&) = delete;

    Event(Event&&) = delete;

    Event& operator=(const Event&) = delete;

    Event& operator=(Event&&) = delete;

    log::Level Level() const noexcept;

    std::string_view FileName() const noexcept;

    std::size_t LineNum() const noexcept;

    std::uint32_t ThreadId() const noexcept;

    Clock::time_point Time() const noexcept;

    //! Get the message written by the user.
    std::string Message() const noexcept;

    //! Get an output stream. The user can write messages into it.
    std::ostringstream& MessageStream() noexcept;

protected:
    explicit Event(log::Level level,
                   std::experimental::source_location location,
                   std::uint32_t thread_id, Clock::time_point time) noexcept;

private:
    log::Level level_;
    std::string_view file_name_;
    std::size_t line_num_;
    std::uint32_t thread_id_;
    Clock::time_point time_;

    std::ostringstream msg_;
}

void Logger::Log(const Event::Ptr event) noexcept {
    if (event->Level() >= level_) {
        if (async_) {
            const std::lock_guard locker {mtx_};
            event_deque_->PushBack(std::move(event));
        } else {
            SyncLog(*event);
        }
    }
}

void FileAppender::Log(const Logger& logger, const Event& event) noexcept {
    const std::lock_guard locker {mtx_};
    file_ << formatter_->Format(logger, event) << std::flush;
}

void StdOutAppender::Log(const Logger& logger, const Event& event) noexcept {
    const std::lock_guard locker {mtx_};
    std::osyncstream {std::cout} << formatter_->Format(logger, event)
                                 << std::flush;
}

Logger::Logger(const std::string_view name, const log::Level level,
               const std::optional<std::size_t> capacity) noexcept :
    name_ {name}, level_ {level}, capacity_ {capacity.value_or(0)} {
    if (capacity_ > 0) {
        async_ = true;
        event_deque_ = std::make_unique<BlockDeque<Event::Ptr>>(capacity_);
        writer_thread_ =
            std::make_unique<std::thread>(&Logger::AsyncLogProc, this);
    } else {
        async_ = false;
    }
}

//! Initialize the default configuration.
cfg::Config::Ptr InitDefaultConfig() noexcept {
    static constexpr std::uint16_t default_port {10000};
    static const std::string default_asset_folder {"assets"};
    static constexpr std::size_t default_alive_time {60};

    const auto config {cfg::RootConfig()};
    config->Lookup<std::uint16_t>(port_tag, default_port, "The listening port");
    config->Lookup<std::size_t>(alive_time_tag, default_alive_time,
                                "The alive time of client (in seconds)");
    config->Lookup<std::string>(asset_folder_tag, default_asset_folder,
                                "The asset folder");
    return config;
}

/**
 * @brief Load a local configuration.
 *
 * @param config An existing configuration.
 * @param file A configuration file.
 */
cfg::Config::Ptr LoadConfig(const cfg::Config::Ptr config,
                            const std::string& file) {
    config->LoadYaml(YAML::LoadFile(file));
    return config;
}

}  // namespace

int main() {
    log::Manager::InitConfig();
    auto config {InitDefaultConfig()};
    const auto curr_dir {std::filesystem::current_path()};

    try {
        // Load the local configuration if it exists.
        static constexpr std::string_view config_file {"config.yaml"};

        if (const auto config_path {curr_dir / config_file};
            std::filesystem::exists(config_path)) {
            config = LoadConfig(config, config_path);
        }
    } catch (const std::exception& err) {
        log::RootLogger()->Log(
            log::Event::Create(log::Level::Warn) << fmt::format(
                "Failed to load local configuration: {}", err.what()));
    }

    try {
        const auto port {config->Lookup<std::uint16_t>(port_tag)->GetValue()};
        const auto alive_time {
            config->Lookup<std::size_t>(alive_time_tag)->GetValue()};
        const auto asset_folder {
            config->Lookup<std::string>(asset_folder_tag)->GetValue()};

        WebServerBuilder<IPv4Addr> builder {};
        builder.SetPort(port)
            .SetAliveTime(std::chrono::seconds {alive_time})
            .SetRootDirectory(curr_dir / asset_folder);

        auto web_server {builder.Create()};
        web_server.Start();
        return EXIT_SUCCESS;

    } catch (const std::exception& err) {
        log::RootLogger()->Log(
            log::Event::Create(log::Level::Error)
            << fmt::format("Failed to run server: {}", err.what()));
        return EXIT_FAILURE;
    }
}

template <typename Key>
void HeapTimer<Key>::Tick() noexcept {
    while (!Empty()) {
        if (auto& node {nodes_.front()}; node.Expired()) {
            const auto callback {std::move(node.callback)};
            const auto key {node.key};
            Pop();

            try {
                assert(callback);
                callback(key);
            } catch (const std::exception& err) {
                logger_->Log(
                    log::Event::Create(log::Level::Error)
                    << fmt::format("Exception raised in timer's callback: {}",
                                   err.what()));
            }
        } else {
            break;
        }
    }
}

template <typename Key>
void HeapTimer<Key>::Invoke(const Key& key) {
    const auto idx {key_to_idx_.at(key)};

    try {
        assert(nodes_[idx].callback);
        nodes_[idx].callback(key);
    } catch (const std::exception& err) {
        logger_->Log(log::Event::Create(log::Level::Error)
                     << fmt::format("Exception raised in timer's callback: {}",
                                    err.what()));
    }

    RemoveByIndex(idx);
    assert(!Contain(key));
}

cfg::Var<std::unordered_set<LoggerConfig>>::Ptr SetListener(
    const cfg::Var<std::unordered_set<LoggerConfig>>::Ptr loggers,
    const ws::log::Manager::Ptr manager) noexcept {
    loggers->AddListener(
        [manager](const std::unordered_set<LoggerConfig>& old_cfgs,
                  const std::unordered_set<LoggerConfig>& new_cfgs) noexcept {
            for (const auto& logger_cfg : new_cfgs) {
                if (const auto cfg {old_cfgs.find(logger_cfg)};
                    cfg != old_cfgs.cend() && *cfg == logger_cfg) {
                    continue;
                }

                // Remove the old logger.
                manager->RemoveLogger(logger_cfg.name);

                // Create a new logger.
                const auto logger {manager->FindLogger(
                    logger_cfg.name, logger_cfg.level, logger_cfg.capacity)};
                if (!logger_cfg.formatter.empty()) {
                    logger->SetDefaultFormatter(logger_cfg.formatter);
                }

                // Add appenders.
                logger->ClearAppenders();
                for (const auto& appender_cfg : logger_cfg.appenders) {
                    Appender::Ptr appender;
                    switch (appender_cfg.type) {
                        case AppenderType::StdOut: {
                            appender = std::make_shared<StdOutAppender>(
                                logger->GetDefaultFormatter());
                            break;
                        }
                        case AppenderType::File: {
                            appender = std::make_shared<FileAppender>(
                                appender_cfg.file, logger->GetDefaultFormatter());
                            break;
                        }
                        default: {
                            assert(false);
                        }
                    }

                    logger->AddAppender(appender);
                }
            }
        });

    return loggers;
}
